/**
 * EventTimelinePanel Component
 *
 * Chronological real-time simulation event log:
 * - Real simulation timestamps generated by the physical engine
 * - Color-coded category tags (Control, Physics, Feedback, Fault, Bus)
 * - Auto-scroll to latest transitions
 */

import React, { useRef, useEffect } from 'react';
import {
  Clock,
  Zap,
  Activity,
  AlertTriangle,
  RotateCw,
  Sliders,
  Radio,
  CheckCircle,
} from 'lucide-react';

export function EventTimelinePanel({ events = [] }) {
  const scrollRef = useRef(null);

  // Auto-scroll to latest event
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [events.length]);

  const getCategoryBadge = (category) => {
    switch (category) {
      case 'control':
        return {
          icon: <Sliders size={12} className="text-cyan-400" />,
          label: 'CONTROL',
          colorClass: 'bg-cyan-950/50 text-cyan-400 border-cyan-800/40',
        };
      case 'physics':
        return {
          icon: <RotateCw size={12} className="text-amber-400" />,
          label: 'PHYSICS',
          colorClass: 'bg-amber-950/50 text-amber-400 border-amber-800/40',
        };
      case 'feedback':
        return {
          icon: <Activity size={12} className="text-emerald-400" />,
          label: 'FEEDBACK',
          colorClass: 'bg-emerald-950/50 text-emerald-400 border-emerald-800/40',
        };
      case 'fault':
        return {
          icon: <AlertTriangle size={12} className="text-red-400" />,
          label: 'INTERLOCK',
          colorClass: 'bg-red-950/50 text-red-400 border-red-800/40',
        };
      case 'can':
        return {
          icon: <Radio size={12} className="text-purple-400" />,
          label: 'TELEM',
          colorClass: 'bg-purple-950/50 text-purple-400 border-purple-800/40',
        };
      default:
        return {
          icon: <Zap size={12} className="text-blue-400" />,
          label: 'SYSTEM',
          colorClass: 'bg-slate-800 text-slate-300 border-slate-700',
        };
    }
  };

  return (
    <div className="event-timeline-container">
      <div className="event-timeline-header">
        <div className="flex items-center gap-2">
          <Clock size={14} className="text-cyan-400" />
          <span className="font-semibold text-xs tracking-wider uppercase text-slate-200">
            Real-Time Simulation Event Log ({events.length} Events)
          </span>
        </div>
        <span className="text-xs text-slate-400">
          Chronological record generated directly by physics model
        </span>
      </div>

      <div className="event-timeline-scroll" ref={scrollRef}>
        {events.length === 0 ? (
          <div className="event-empty-state">
            <span className="text-xs text-slate-400">No events recorded yet. Start motor or adjust speed to generate events.</span>
          </div>
        ) : (
          <div className="event-timeline-list">
            {events.map((evt, idx) => {
              const badge = getCategoryBadge(evt.category);
              return (
                <div key={evt.id || idx} className="event-card">
                  {/* Timestamp */}
                  <div className="event-timestamp">
                    <span className="font-mono text-cyan-300 font-bold">
                      {String(evt.time).padStart(4, '0')}s
                    </span>
                  </div>

                  {/* Category Pill */}
                  <div className={`event-category-badge ${badge.colorClass}`}>
                    {badge.icon}
                    <span>{badge.label}</span>
                  </div>

                  {/* Title & Detail */}
                  <div className="event-content">
                    <div className="event-title">{evt.title}</div>
                    {evt.detail && (
                      <div className="event-detail">{evt.detail}</div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}
